#include <iostream>

int main() {
    // Non-nesting loops: safe and standard practice
    int sum1 = 0;
    for (int i = 1; i <= 3; ++i) {
        sum1 += i;
    }

    int sum2 = 0;
    for (int i = 1; i <= 3; ++i) {
        sum2 += i * 2;
    }

    // Nested block demonstrating variable shadowing
    int value = 100;
    {
        // Inner scope shadows outer 'value'
        int value = 5;
        std::cout << "Inner value: " << value << "\n";
    }
    std::cout << "Outer value: " << value << "\n";
    std::cout << "Sums: " << sum1 << " " << sum2 << "\n";
    return 0;
}

#include <iostream>

void counterFunction() {
    // Initialized only once on the first call
    static int staticCount = 1;
    // Reallocated and reinitialized on every invocation
    int autoCount = 1;

    staticCount++;
    autoCount++;

    std::cout << "staticCount: " << staticCount 
              << ", autoCount: " << autoCount << "\n";
}

int main() {
    counterFunction();
    counterFunction();
    counterFunction();
    return 0;
}

#include <iostream>

void increment(int n) {
    n++;
    std::cout << "n inside function: " << n << "\n";
}

int main() {
    int x = 1;
    std::cout << "Before call, x: " << x << "\n";
    increment(x);
    std::cout << "After call, x: " << x << "\n";
    return 0;
}
